def words():
    result, seen = [], set()
    for hint, group in WORD_GROUPS.items():
        for word in group.split():
            if word not in seen and word not in {'цариградско', 'кисело', 'ленен'} and 3 <= len(word) <= 20:
                seen.add(word)
                result.append({'word': word, 'hint': hint})
    return result
